package com.example.Hospital.Management.System.services; import com.example.Hospital.Management.System.entities.*; import com.example.Hospital.Management.System.dtos.*; import com.example.Hospital.Management.System.repositories.*; import com.example.Hospital.Management.System.exceptions.*; import org.springframework.stereotype.Service; import java.util.*; import java.time.*; @Service public class AdmissionService{private final AdmissionRepository r;private final PatientRepository pr;private final RoomRepository rr;public AdmissionService(AdmissionRepository r,PatientRepository pr,RoomRepository rr){this.r=r;this.pr=pr;this.rr=rr;} private Admission find(Long id){return r.findById(id).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Admission not found"));} private AdmissionDTO dto(Admission e){return AdmissionDTO.builder().id(e.getId()).admitDate(e.getAdmitDate()).dischargeDate(e.getDischargeDate()).patientId(e.getPatient().getId()).roomId(e.getRoom().getId()).build();} private void apply(Admission e,AdmissionDTO d){Patient p=pr.findById(d.getPatientId()).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Patient not found"));Room room=rr.findById(d.getRoomId()).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Room not found"));if(r.countByRoomIdAndDischargeDateIsNullAndIsActiveTrue(room.getId())>=room.getCapacity()&&(e.getId()==null||!room.getId().equals(e.getRoom().getId())))throw new BusinessException("Room is already at capacity");e.setAdmitDate(d.getAdmitDate());e.setDischargeDate(d.getDischargeDate());e.setPatient(p);e.setRoom(room);} public AdmissionDTO create(AdmissionDTO d){Admission e=new Admission();apply(e,d);return dto(r.save(e));} public List<AdmissionDTO> all(){return r.findByIsActiveTrue().stream().map(this::dto).toList();} public AdmissionDTO get(Long id){return dto(find(id));} public AdmissionDTO update(Long id,AdmissionDTO d){Admission e=find(id);apply(e,d);return dto(r.save(e));} public void delete(Long id){Admission e=find(id);e.setIsActive(false);r.save(e);} public AdmissionDTO discharge(Long id){Admission e=find(id);e.setDischargeDate(LocalDate.now());return dto(r.save(e));} public List<AdmissionDTO> floor(Integer f){return r.activeOnFloor(f).stream().map(this::dto).toList();}}
